Definition H7b (R : bvmap 5 word) (M : word -> option byte) (model : Model) (cr : credit) (s : PM.vstr) (be : bool) : Prop :=
  PECH.hcore L R0 M0 model0 sp ra LB0 R M model /\ PECHK.vstr_at M (PECH.fb sp + 792) s
